mapper.select:
SELECT d.day_result_id,s.shop_id,s.business_date
FROM oa_attendance_schedule s LEFT JOIN oa_attendance_day_result d ON d.schedule_id=s.schedule_id
WHERE s.user_id=#{userId} AND s.shop_id=#{shopId} AND s.status IN ('PUBLISHED','CHANGED')
 AND TIMESTAMP(s.business_date,s.start_time_snapshot) < #{end}
 AND TIMESTAMP(CASE WHEN s.cross_day_snapshot=1 THEN DATE_ADD(s.business_date,INTERVAL 1 DAY) ELSE s.business_date END,s.end_time_snapshot) > #{start}
ORDER BY s.business_date,s.schedule_id
